mapper.select:
select concat('20', #{year}) as year, count(*) as totCnt
from statistic.request_info ri
where date_format(ri.create_date, '%Y') = concat('20', #{year});

select date_format(create_date, '%Y-%m') as yearMonth, count(*) as totCnt
from statistic.request_info ri
where date_format(ri.create_date, '%Y-%m') = #{yearMonth};
